DO $$ DECLARE f record;d text;BEGIN FOR f IN SELECT p.oid FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN('generate_time_tasks','task_daily_summary') LOOP d:=pg_get_functiondef(f.oid);d:=replace(d,'current_user<>''postgres''','session_user<>''postgres''');d:=replace(d,'auth.role()<>''service_role''','auth.role() IS DISTINCT FROM ''service_role''');EXECUTE d;END LOOP;END $$;
CREATE OR REPLACE FUNCTION public.task_ledger_resolution() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i uuid;c uuid;t public.tasks;balance numeric;BEGIN SELECT installment_id INTO i FROM public.receipt_allocations WHERE id=NEW.id;IF i IS NULL THEN RETURN NEW;END IF;balance:=public.task_installment_balance(i);IF balance<=0 THEN UPDATE public.tasks SET status='done',completed_at=now(),outcome_note='اكتمل السداد من التخصيصات المعتمدة',updated_at=now() WHERE entity_type='installment' AND entity_id=i AND status='open' AND type='installment_due';SELECT contract_id INTO c FROM public.installments WHERE id=i;IF NOT EXISTS(SELECT 1 FROM public.installments x WHERE x.contract_id=c AND x.status<>'waived' AND public.metrics_is_overdue(x.due_date,(now() AT TIME ZONE 'Asia/Riyadh')::date,(SELECT grace_days FROM public.app_settings WHERE id=1)) AND public.task_installment_balance(x.id)>0) THEN UPDATE public.tasks SET status='done',completed_at=now(),outcome_note='انتهى سبب التصعيد من السجل المعتمد',updated_at=now() WHERE entity_type='contract' AND entity_id=c AND type='installment_escalation' AND status='open';END IF;END IF;RETURN NEW;END $$;
CREATE OR REPLACE TRIGGER task_ledger_resolution AFTER INSERT ON public.receipt_allocations FOR EACH ROW EXECUTE FUNCTION public.task_ledger_resolution();REVOKE ALL ON FUNCTION public.task_ledger_resolution() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.log_task_opportunity_activity_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF length(coalesce(NEW.notes,''))>2000 OR (NEW.next_action_at IS NOT NULL AND nullif(btrim(NEW.next_action),'') IS NULL) THEN RAISE EXCEPTION 'حدد الإجراء القادم مع موعده';END IF;PERFORM public._safety_audit('OPPORTUNITY_ACTIVITY_RECORDED','opportunity_activities',NEW.id::text,NULL,to_jsonb(NEW),'تسجيل النشاط والإجراء القادم');RETURN NEW;END $$;CREATE OR REPLACE TRIGGER task_opportunity_activity_audit AFTER INSERT ON public.opportunity_activities FOR EACH ROW EXECUTE FUNCTION public.log_task_opportunity_activity_audit();REVOKE ALL ON FUNCTION public.log_task_opportunity_activity_audit() FROM PUBLIC,anon,authenticated;
SELECT to_regprocedure('public.task_ledger_resolution()') IS NOT NULL AS ledger_resolution_ready;